#ifndef IGRAPH_PRIVATE_CONFIG_H
#define IGRAPH_PRIVATE_CONFIG_H

/* igraph's private feature configuration.
 *
 * Upstream this file is generated by CMake from src/config.h.in by probing the
 * machine doing the build.  gAtoms ships one copy inside the package and has to
 * build it on Windows, Linux and macOS without running CMake at install time,
 * so the probe results are expressed here as compile-time platform tests
 * instead of being frozen at one host's values.
 *
 * The Windows branch reproduces, token for token, what CMake generated for the
 * bundled copy on MinGW-w64, so the Windows build is unchanged.  The other
 * branch gives the values a POSIX host yields.  Every entry that differs is a
 * probe of a Microsoft-specific facility -- the _umul128 / _BitScan* / _stricmp
 * / _configthreadlocale family of CRT intrinsics -- which does not exist there,
 * so those macros must stay undefined and igraph's portable fallbacks are used.
 * Macros that describe gAtoms' own build choices rather than a platform probe
 * (HAVE_INFOMAP, INTERNAL_*) are outside the conditional.
 *
 * Called out because they are easy to get wrong:
 *   HAVE__UMUL128   its presence makes src/random/random.c include <intrin.h>,
 *                   which does not exist on Linux or macOS.
 *   HAVE__POPCNT*   select the _popcnt/_BitScanForward intrinsics in
 *                   igraph_bitset.h.
 *   HAVE__STRICMP,
 *   HAVE__STRNICMP  are only consulted by internal/hacks.h when
 *                   strcasecmp()/strncasecmp() are unavailable; on POSIX those
 *                   functions exist and the HAVE_STRCASECMP / HAVE_STRNCASECMP
 *                   probes are set instead.
 */

#if defined(_WIN32)

/* ---- Windows (MinGW-w64 / MSVC): the values the bundled copy was probed in */

#define HAVE_STRCASECMP 1
#define HAVE_STRNCASECMP 1
#define HAVE__STRICMP 1
#define HAVE__STRNICMP 1
#define HAVE_STRDUP 1
/* #undef HAVE_STRNDUP */
/* #undef HAVE_USELOCALE */
/* #undef HAVE_XLOCALE */
#define HAVE__CONFIGTHREADLOCALE 1

#define HAVE_BUILTIN_OVERFLOW 1

#define HAVE__UMUL128 1
/* #undef HAVE___UMULH */
#define HAVE___UINT128_T 1

#define HAVE__POPCNT64 1
#define HAVE__POPCNT 1
#define HAVE__BITSCANFORWARD64 1
#define HAVE__BITSCANFORWARD 1
#define HAVE__BITSCANREVERSE64 1
#define HAVE__BITSCANREVERSE 1

#if defined(_MSC_VER)
#  define IGRAPH_TLS_KEYWORD __declspec(thread)
#else
#  define IGRAPH_TLS_KEYWORD __thread
#endif

#else

/* ---- POSIX (Linux/glibc, macOS/libSystem, and other Unix-like hosts) ------ */

#define HAVE_STRCASECMP 1
#define HAVE_STRNCASECMP 1
/* #undef HAVE__STRICMP */
/* #undef HAVE__STRNICMP */
#define HAVE_STRDUP 1
/* #undef HAVE_STRNDUP */
/* #undef HAVE_USELOCALE */
/* #undef HAVE_XLOCALE */
/* #undef HAVE__CONFIGTHREADLOCALE */

#if defined(__GNUC__) || defined(__clang__)
#  define HAVE_BUILTIN_OVERFLOW 1
#endif

/* #undef HAVE__UMUL128 */
/* #undef HAVE___UMULH */

/* __uint128_t exists on 64-bit GCC and Clang, which covers the POSIX hosts this
 * package builds on; elsewhere igraph falls back to igraph_i_umul128(). */
#if (defined(__GNUC__) || defined(__clang__)) && \
    (defined(__SIZEOF_INT128__) || defined(__x86_64__) || defined(__aarch64__))
#  define HAVE___UINT128_T 1
#endif

/* #undef HAVE__POPCNT64 */
/* #undef HAVE__POPCNT */
/* #undef HAVE__BITSCANFORWARD64 */
/* #undef HAVE__BITSCANFORWARD */
/* #undef HAVE__BITSCANREVERSE64 */
/* #undef HAVE__BITSCANREVERSE */

#define IGRAPH_TLS_KEYWORD __thread

#endif /* _WIN32 */

/* ---- gAtoms build choices, identical on every platform ------------------- */

/* #undef HAVE_GLPK */
/* #undef HAVE_LIBXML */
#define HAVE_INFOMAP 1

#define INTERNAL_BLAS 1
#define INTERNAL_LAPACK 1
#define INTERNAL_ARPACK 1
#define INTERNAL_GMP 1

#define IGRAPH_F77_SAVE static IGRAPH_TLS_KEYWORD
#define IGRAPH_THREAD_LOCAL IGRAPH_TLS_KEYWORD

#endif
